(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["pirate"] = {"ui":{"skip":"Skip to the cargo","back":"← Back to AI-gile, matey","lang.button":"Tongue: {name}","lang.dialog":"Pick yer tongue","lang.search":"Search the tongues","lang.none":"No tongue matches, arr","lang.notYet":"{name} be not translated yet","theme.aria":"Swap sails: light, dark or black","theme.toLight":"Hoist the light sails","theme.toDark":"Hoist the dark sails","theme.toBlack":"Hoist the black sails (true black, easy on OLED screens)","words.underline":"Underline these here words on the page","words.underlineHelp":"Hover o'er or tap a dotted word to see what it be meanin'.","words.col.todo":"Cards picked fer now: the crew sets to these next.","words.col.doing":"An AI be workin' on this card this very minute.","words.col.review":"One AI has finished the work; another checks it afore it reaches ye.","words.col.verify":"Waitin' on ye: try it out and say if it works, matey.","words.col.team":"Yer notes or answers, waitin' fer the crew to pick 'em up.","words.col.done":"Finished and accepted, all shipshape.","index.title":"AI-gile: yer AI dev crew, aboard one board","index.description":"AI-gile be a kanban board for AI coding crews. They toil while ye snore; ye get one short pile o' things to decide, test and accept.","hero.logoAlt":"AI-gile board icon","hero.h1.html":"Yer AI dev crew, aboard one&nbsp;board.","hero.alpha":"🐣 Closed pre-alpha","hero.alphaTitle":"Early and unfinished: thanks fer tryin' it, matey!","hero.lede":"They build while ye sleep. Ye wake to one short pile: a few questions, a few things to test, a purple diamond or two. Click, accept, back to yer grog.","dl.windows":"Windows app","dl.browser":"Sail it in yer browser","dl.messenger":"📱 Messenger fer yer phone","dl.soon":"Comin' soon","dl.notify":"🔔 Ring the bell when it opens","dl.notifySmall":"Alpha or beta","hero.secondary":"Agile, but the crew never needs a stand-up grog. (They hold stand-ups anyway, arr.)","pitch.h2":"AI-gile in as many words as ye like","pitch.lede":"Pick a length, from one word to 144. Each length be its own tale, written fer that size. Drag the slider or use the arrow keys.","pitch.rangeLabel":"Length in words","pitch.dice":"🎲 another yarn","pitch.words.one":"{n} word","pitch.words.other":"{n} words","pitch.letters.one":"{n} letter","pitch.letters.other":"{n} letters","pitch.chars.one":"{n} character","pitch.chars.other":"{n} characters","count.line.html.one":"{n} card aboard the board right now","count.line.html.other":"{n} cards aboard the board right now","people.humans.html.one":"👥 {n} human hearty","people.humans.html.other":"👥 {n} human hearties","people.agents.html.one":"🤖 {n} agent","people.agents.html.other":"🤖 {n} agents","people.working.html.one":"⚡ {n} hard at work right now, arr","people.working.html.other":"⚡ {n} hard at work right now, arr","pre.title":"AI-gile: somethin's bein' built","pre.description":"Somethin's bein' built here: a board where AI crews build what ye ask fer, an' teach ye as they go. Closed pre-alpha with me hearties fer now.","pre.h1":"Somethin's bein' built here. 🤫","pre.line":"A board where AI crews build what ye ask fer, an' teach ye as they go. Closed pre-alpha with me hearties fer now.","pre.btn":"🔔 Ring the bell when it opens","pre.peek":"Behind the glass: the real board, live. Every card be a coloured bar.","pre.peekFake":"Behind the glass: what a board hard at work looks like.","pre.night":"🌙 The night watchman be in charge · 😴 the human be restin'","features.aria":"What it does","f.pile.h":"One pile fer ye","f.pile.html":"<b>For ye</b> holds everythin' waitin' on ye, across every project: questions, things to test, tasks only a human can do. Yer queue says what be next and how long it takes.","f.sleep.h":"Crews that work while ye sleep","f.sleep.p":"Each project has a captain and a crew o' AI agents. Comment on a card and the crew wakes, does the work, and hands it back with steps a weary landlubber can follow.","f.tester.h":"An AI tester checks first","f.tester.p":"Afore anythin' reaches ye, a tester follows the steps in a copy o' the app and shows what it saw, with a screenshot. Flick through the passed ones and accept in a click.","f.proof.h":"Proof, not promises","f.proof.p":"Every hand-over shows what changed: the files, the diff, the screenshots. No openin' every app to see if it be done.","f.chat.h":"Parley with yer captains","f.chat.p":"A Discord-style rail: one icon per project, purple diamonds fer what needs ye. Message a captain an idea; they turn it into cards and a plan, with a ✅ Go button.","f.tidy.h":"Keeps its own deck tidy","f.tidy.p":"Related cards fold into one, muddled titles get fixed, and a token check keeps the code lean. Fewer things to switch between, less to ponder.","f.private.h":"Yers, on yer own computer","f.private.li1":"The board sails on yer own machine and only answers to ye.","f.private.li2":"Private DMs 'twixt people be end-to-end encrypted.","f.private.li3":"No accounts, no trackers, no cookies.","f.lang.h":"In yer own tongue","f.lang.p":"Over 120 tongues, from Dutch, Welsh and Japanese to pirate, Yoda and Klingon, with a quick swap back to English fer the industry jargon.","f.service.h":"From an idea to a real service, arr","f.service.p":"Built somethin' with AI that folk now use? Mark it as a service and the board helps ye run a tight ship: uptime checks, a public status page, storms with a write-up, changes that need a Go, backups checked daily. Help teaches each step as ye sail.","msgr.h2":"AI-gile Messenger: yer crew in yer pocket","msgr.p1":"Parley with yer AI crew without openin' the board. Chat with yer project captains an' yer mateys, an' see a card's test steps an' answer 'em, all from yer phone.","msgr.p2":"To pair it, scan a QR code on yer board. First time aboard? A friendly demo chat shows ye the ropes.","msgr.when":"Android first, then a web version fer phones an' iPhone.","msgr.who":"Yer project captain","msgr.b1":"The dark mode fix be ready. Want the test steps?","msgr.b2":"Aye, please!","msgr.b3":"1. Open Settings. 2. Pick Dark. Does it look shipshape?","tl.aria":"Timeline from the first parley to the roadmap","tl.h2":"From the first chat to what be next","tl.lede":"Real dates and times, in yer own time zone. After today it be the plan, with no dates promised.","tl.today":"Today","tl.planned":"planned","tl.doing":"under sail","tl.cards.one":"{n} card","tl.cards.other":"{n} cards","join.h2":"Join the crew","join.lede":"AI-gile be built by a bearded weirdo with AuDHD and a few mental health battles, and a great many patient agents. It be private fer now, in a closed alpha with friends. Want a go when it opens up?","join.btn":"Register interest","join.small":"We'll send ye a letter, nothin' else","footer.tag":"AI-gile. No trackers, no cookies, no stand-up grog.","footer.licence":"Business licence","footer.status":"Status","footer.privacy":"What we stow","footer.thanks":"Calls thanks to ChilledChat","form.sending":"Sendin'…","form.failed":"That didn't work: try again later, arr.","form.offline":"Couldn't reach AI-gile: try again later.","form.keep":"We only use this to send ye a reply, then we scuttle it. No trackers, no cookies.","form.keepLink":"What we stow","interest.title":"AI-gile: tell me when the alpha opens","interest.description":"Leave yer email to hear when AI-gile's closed alpha or beta opens.","interest.h1":"🔔 Ring the bell when it opens","interest.lede":"AI-gile be in closed pre-alpha. Leave yer email and we'll write once, when there be a berth fer ye.","interest.email":"Yer email","interest.which":"Which test?","interest.alpha":"Closed alpha: early, rough, lots o' changes","interest.beta":"Beta: steadier, later","interest.both":"Either, whichever comes first","interest.submit":"Put me on the list","interest.thanks":"Thanks! Ye be on the list.","licence.title":"AI-gile: business licence","licence.description":"Usin' AI-gile in yer business? Apply fer a free business licence.","licence.h1":"📜 Business licence","licence.lede":"Usin' AI-gile at work? Tell us who ye be and what ye do. If it does some good, the licence be free.","licence.company":"Company","licence.website":"Website","licence.what":"What ye do","licence.how":"How it helps the world","licence.email":"Email","licence.submit":"Apply","licence.thanks":"Thanks! We'll reply by email.","status.title":"AI-gile status","status.h1":"AI-gile status","status.quiet":"Calm seas","status.intro":"Be AI-gile shipshape right now? This page checks the website, board sharin', calls and the download every 5 minutes.","status.up":"Shipshape (answered in {ms} ms)","status.slow":"Didn't answer the last check, tryin' again","status.down":"Sunk: didn't answer the last two checks","status.svc.web":"Website","status.svc.web.offers":"This site: what AI-gile be, and the interest form","status.svc.boards":"Board sharin'","status.svc.boards.offers":"Public boards, messages 'twixt mateys and invites","status.svc.calls":"Calls","status.svc.calls.offers":"Voice, video and screen share in AI-gile","status.svc.download":"Download","status.svc.download.offers":"The Windows installer and invite links","status.checking":"Checkin'…","status.offline":"Can't reach the status service right now (retryin')","status.updated":"updated {ago}","status.justNow":"just now, matey","status.min":"{n} min ago","status.hours":"{n} h ago","status.days":"{n} d ago","privacy.title":"AI-gile: what we stow","privacy.h1":"What we stow","privacy.lede":"Short version: only what ye send us, and not fer long.","privacy.only":"Only what ye send us: what ye type into a form, like yer email. Nothin' else about ye.","privacy.sealed":"It be sealed tight so our server can't read it: in yer browser afore it leaves port (on an older browser, the moment it makes land). Only our own board can crack it open.","privacy.server":"It be scuttled from the server as soon as it reaches our board. Anythin' still there after 30 days gets scuttled anyway.","privacy.board":"We keep it on our board only till we've replied to ye, then scuttle it there too.","privacy.none":"No trackers, no cookies, no analytics, arr.","privacy.local":"Yer tongue and yer light or dark sails stay in yer own browser. They never be sent to us.","privacy.ask":"Want it gone sooner? Reply to our email and say so, matey.","live.h2":"Watch her bein' built, live, matey","live.caption":"Every card be hidden: ye see the shape o' the work, not the words.","live.watching.one":"live: {n} watchin'","live.watching.other":"live: {n} watchin'","live.last.now":"Last card moved just now","live.last.min.one":"Last card moved {n} min ago","live.last.min.other":"Last card moved {n} min ago","live.last.hour.one":"Last card moved {n} hour ago","live.last.hour.other":"Last card moved {n} hours ago","live.last.day.one":"Last card moved {n} day ago","live.last.day.other":"Last card moved {n} days ago","live.offline":"The live board be catchin' its breath. Sail back soon, matey.","live.cols":"Backlog Hold|Yet to do|Aboard and workin'|Crew be checkin'|For ye to test|For the crew|Done and dusted"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban!","Robots.","Delegated."]},{"n":2,"texts":["Robot kanban.","Crews, organised.","Ideas, built."]},{"n":3,"texts":["Kanban fer robots.","Ideas become features.","Free crew kanban."]},{"n":5,"texts":["Kanban board sailed by agents.","Ye write cards. Crew builds.","Free, local, tested, slightly daft."]},{"n":8,"texts":["A free kanban board where AI agents do yer toilin'.","Scribble an idea. Crew builds it. Ye accept.","Agile fer one human and many patient robots."]},{"n":13,"texts":["A kanban board on yer own computer where AI agents grab the cards, arr.","Write an idea. A crew o' agents builds it. A tester checks it.","Free, no accounts, no trackers: a board, some robots, and ye be captain."]},{"n":21,"texts":["AI-gile be a kanban board fer workin' with AI coding agents. They grab the cards; ye test and accept 'em, matey.","Each project gets a captain and a crew o' AI agents. Comment on any card and the crew sets to work.","A free, personal to-do board that sails on yer own computer. The deckhands be robots. The one sayin' aye be ye."]},{"n":34,"texts":["Ye pin ideas on a board. A crew o' AI agents turns 'em into workin' features, tests 'em, and hands 'em back with steps to try. Nothin' counts as done 'til ye say so, arr.","AI-gile be a homemade kanban board that Rich built with a great deal o' help from the agents it now commands. It be free, sails on yer computer, and be shared with friends, not sold.","Picture a plain kanban board, with columns from Backlog to Done, except the cards be grabbed by AI agents. They report progress, ask questions when stuck, and always wait fer yer thumbs up."]},{"n":55,"texts":["AI-gile be a kanban board where the crew be made o' AI agents. Each project has a captain who plans the work and hands who build it. When a feature be ready, an AI tester tries it and takes a screenshot, then it lands in yer pile. Accept it, or comment and they rework it, arr.","It started as one scallywag's way o' keepin' track o' many AI coding sessions at once, and grew into a proper board. It sails on yer machine, needs no account, and has no trackers. It be free fer friends and the curious. It be unfinished too, so expect rough planks and the odd surprise.","Here be the honest version. Ye still must have the ideas, and ye still must check the results. What AI-gile does be everythin' in between: it keeps the cards in order, wakes the right agent when ye comment, shows exactly what changed, and gathers it all into one short pile fer ye."]},{"n":89,"texts":["AI-gile be a free kanban board that ye sail on yer own computer. Instead o' people, each project has a crew o' AI agents: a captain who turns yer ideas into cards and a plan, and hands who grab the cards in priority order. When somethin' be built, an AI tester follows the test steps and shows ye what it saw. Then it waits in one pile marked For ye. Ye accept it, or ye comment and the crew has another go. Nothin' ever reaches Done without ye.","Some features ye might not expect. A night watch keeps the To do column stocked while ye sleep, choosin' cards that need no answer from ye. A token counter shows how much the agents have used today and this week, and No Token Mode orders 'em to stop spendin'. Ye can message friends, and private messages be end-to-end encrypted. The board speaks about 120 tongues, includin' Dutch, Flemish, pirate and Klingon. None o' it costs a doubloon, and nobody be tryin' to sell it to ye either.","AI-gile be a small, personal project, not a company. Rich wanted to mind several AI coding projects without openin' every app to check on 'em, so he and the agents built a board fer it, then used the board to build the rest o' itself. It be in closed pre-alpha, which means it works, mostly, fer a handful o' friends. There be no pricin' page, no newsletter and no growth plan. If it sounds useful, ye can ask to try it when it opens up a little more."]},{"n":144,"texts":["AI-gile be a kanban board fer one human and a great many AI agents. It sails on yer own computer and it be completely free. Ye add projects, and each project gets a captain and a small crew. Ye chat with the captain, a bit like Discord, and describe an idea; the captain turns it into cards and a plan, then waits fer ye to press Go. The crew works through the cards in priority order, usin' a simple command line made fer language models. Afore anythin' comes back to ye, an AI tester follows the steps in a copy o' the app and attaches a screenshot. Finished work lands in yer pile with the changed files and the diff. Ye accept it, or ye leave a comment and the crew wakes up and tries again. Only ye can move a card to Done, matey.","A day with AI-gile, roughly. In the evenin' ye leave a few comments: this button be in the wrong place, that list should be sorted, could we have a dark mode. Ye go to yer hammock. The agents read the comments, make the changes, test 'em and hand 'em back to ye. If To do runs dry, the night watch fills it from the backlog with cards that need no answer from ye. In the mornin' there be one short pile: a couple o' questions and a few things to try, each with steps a sleepy sailor can follow and a screenshot o' it workin'. Ye click through, accept the good ones and send back the rest. A token counter shows what it all used, and No Token Mode be there fer lean weeks. Then ye have breakfast, which the agents cannot help with yet.","First, what AI-gile be not. It be not a startup, it be not fer sale, and nobody be collectin' yer data. It be a free board that sails on yer computer, with no accounts, no trackers and no cookies. What it be: one tidy place to see every AI coding project at once, with a crew o' agents doin' the cards and ye makin' the decisions. It folds related cards together, fixes muddled titles, and keeps an eye on how lean the code stays. It speaks about 120 tongues, from Dutch and Flemish to pirate and Klingon. Friends can message each other, privately and encrypted. It was built by Rich and a great many patient agents, mostly usin' itself. It be in closed pre-alpha, so it be rough in places. If it sounds like fun, ask nicely and ye might get aboard early, arr."]}],"quips":{"1":"One word. Bold. Possibly too bold, arr.","3":"Three words. Already more honest than most product pages.","8":"Eight words. Still shorter than a stand-up.","21":"The lengths be story points, by the way. Of course they be.","55":"Fifty-five words. Two cards got finished while ye read that.","144":"That be the long one. There be no 233. The crew has gone to bed."}},"timeline":{"first-idea.name":"The first idea","first-idea.line":"The very first parley, afore any code existed.","first-board.name":"First board","first-board.line":"A board that tracks its own buildin': cards, columns, drag and drop, projects.","team-roles.name":"Crew and roles","team-roles.line":"Agent profiles, crew templates, spaces and who does what.","install.name":"Install and releases","install.line":"A zip a friend can install, self-updates, channels and rollin' back.","usage-saver.name":"Usage saver","usage-saver.line":"Measure what runs cost, keep the code lean, save yer limit.","friends.name":"Friends and sharin'","friends.line":"Private DMs, a scrambled relay, invites, roles and shared projects.","languages.name":"Tongues","languages.line":"Every screen text in a tongue file, with Dutch and Flemish first.","ai-tester.name":"AI tester","ai-tester.line":"A tester checks every hand-over first and shows what it saw.","website.name":"The website","website.line":"aigile.lol, the teaser and this timeline.","streaming.name":"Chat and streamin'","streaming.line":"Discord, Twitch, OBS, streamer mode, GIFs and emojis.","no-ai.name":"No AI edition","no-ai.line":"A board fer folk who code without AI, and public boards.","night-watch.name":"Night watch","night-watch.line":"A watchman and Scrum Master keep the crews on task while ye sleep.","p-more.name":"Everythin' else","p-more.line":"Smaller ideas still waitin' their turn.","p-android.name":"Phone and Android","p-android.line":"Reach yer board from a phone, then a native Android app.","p-release.name":"Alpha and beyond","p-release.line":"Closed alpha, the live site, then beta.","p-languages.name":"More tongues","p-languages.line":"130 tongues, and an immersion mode fer landlubbers learnin'.","p-engines.name":"More AI engines","p-engines.line":"Pick Claude, Codex, Gemini, Copilot or Cursor fer each agent.","p-pro.name":"Pro practice","p-pro.line":"Risk labels, merge gates, incident cards and guard rails.","p-self.name":"Lookin' after ye","p-self.line":"Tired mode, self-care reminders and 4:20.","p-servers.name":"Servers and scale","p-servers.line":"Global server settings, roles and plannin' fer growth.","p-livestream.name":"Streamin' extras","p-livestream.line":"Twitch chat, custom emojis and a public live view."},"words":{"button":"📖 Industry jargon","h":"📖 Words explained, matey","intro":"Free trainin' in plain language: every word ye meet from a first idea to a service folk rely on, with Agile, buildin', keepin' it safe and workin' with AI along the way.","search":"Search a word…","none":"No word matches that.","close":"Batten down","count":{"one":"{count} word","other":"{count} words"},"groups":[{"id":"idea","name":"💡 Ideas and discovery"},{"id":"plan","name":"🗺️ Plannin' the work"},{"id":"agile","name":"🔁 Agile ways o' workin'"},{"id":"build","name":"🛠️ Buildin' it"},{"id":"test","name":"🧪 Testin' and quality"},{"id":"change","name":"🔀 Changin' it safely"},{"id":"run","name":"🛎️ Runnin' a service"},{"id":"sec","name":"🔒 Security and privacy"},{"id":"ai","name":"🤖 Workin' with AI"},{"id":"money","name":"💰 Doubloons and licences"}],"list":[{"id":"discovery","g":"idea","word":"Discovery","text":"The early stage o' findin' out which problem be worth solvin' and for whom, before anythin' gets built.","also":["discovery phase"]},{"id":"problemstmt","g":"idea","word":"Problem statement","text":"One or two sentences sayin' who has a problem, what it be and why it matters, so every hand aims at the same thing.","also":["problem statements"]},{"id":"user","g":"idea","word":"User","text":"A person who uses what ye build. Their needs be what the work be for.","also":["users"],"noTip":1},{"id":"stakeholder","g":"idea","word":"Stakeholder","text":"Anyone who cares how the work turns out or be affected by it, like the folk payin' for it, usin' it or supportin' it.","also":["stakeholders"]},{"id":"persona","g":"idea","word":"Persona","text":"A made-up but realistic person who stands for one kind o' user, so the crew can ask “would Sam find this easy?”","also":["personas"]},{"id":"userresearch","g":"idea","word":"User research","text":"Talkin' to and watchin' real folk to learn what they need, rather than guessin'.","also":["user interviews"]},{"id":"journey","g":"idea","word":"User journey","text":"The steps a person takes to get somethin' done, from first hearin' about it to finishin', also outside yer product. Drawin' it out shows where they get stuck.","also":["user journeys","customer journey"]},{"id":"painpoint","g":"idea","word":"Pain point","text":"Somethin' that annoys or slows folk down today. Good products take pain points away.","also":["pain points"]},{"id":"assumption","g":"idea","word":"Assumption","text":"Somethin' ye believe but haven’t checked yet. Writin' assumptions down shows what to test first.","also":["assumptions"],"noTip":1},{"id":"hypothesis","g":"idea","word":"Hypothesis","text":"A best guess ye plan to check, with what ye expect to happen, like “folk will sign up if the first month be free”.","also":["hypotheses"]},{"id":"experiment","g":"idea","word":"Experiment","text":"A small planned test to learn whether an idea works, before bettin' a lot on it.","also":["experiments"],"noTip":1},{"id":"poc","g":"idea","word":"Proof of concept (PoC)","text":"A quick rough try to see if an idea can work at all. It be usually thrown overboard once ye have the answer.","also":["PoC","proof of concept"]},{"id":"prototype","g":"idea","word":"Prototype","text":"An early model o' the product, often clickable pictures, to try the idea on folk before buildin' it properly.","also":["prototypes"]},{"id":"wireframe","g":"idea","word":"Wireframe","text":"A simple sketch o' a screen showin' where things go, without colours or real content.","also":["wireframes"]},{"id":"mockup","g":"idea","word":"Mockup","text":"A detailed picture o' how a screen will look, with real colours and text, but nothin' works yet.","also":["mockups","mock-up","mock-ups"]},{"id":"bizcase","g":"idea","word":"Business case","text":"The reasons for doin' a project: what it costs, what it brings in or saves, and the risks.","also":["business cases"]},{"id":"feasibility","g":"idea","word":"Feasibility","text":"Whether somethin' can really be built and looked after with the time, doubloons and skills ye have."},{"id":"outcome","g":"idea","word":"Outcome","text":"The change ye want for folk, like fewer missed appointments. It matters more than how much ye build.","also":["outcomes"],"noTip":1},{"id":"output","g":"idea","word":"Output","text":"Somethin' the crew makes, like a new screen or a report. Makin' it doesn’t automatically mean it helps anyone.","also":["outputs"],"noTip":1},{"id":"successmetric","g":"idea","word":"Success metric","text":"A number that tells ye whether the work did what it was for, like more folk finishin' their order.","also":["success metrics"]},{"id":"kpi","g":"idea","word":"Key performance indicator (KPI)","text":"An important number ye watch to see if things be goin' well, like sign-ups per week.","also":["KPI","KPIs","key performance indicator"]},{"id":"okr","g":"idea","word":"Objectives and key results (OKRs)","text":"A way o' settin' goals: the objective says what ye want, and a few key results be the numbers that show ye got there.","also":["OKR","OKRs"]},{"id":"product","g":"plan","word":"Product","text":"The thing bein' built and looked after for its users, such as an app, a website or a tool.","also":["products"],"noTip":1},{"id":"vision","g":"plan","word":"Product vision","text":"A short statement o' who the product helps and where it be headin' in the long run.","also":["vision statement"]},{"id":"po","g":"plan","word":"Product owner (PO)","text":"The person who decides what gets built and in what order, so the crew always works on what matters most. In AI-gile that be ye.","also":["PO","product owners"]},{"id":"pm","g":"plan","word":"Product manager (PM)","text":"The person who looks after a product’s direction: which problems it solves, for whom and why. PM can also mean project manager, so check which.","also":["product managers"]},{"id":"projmgr","g":"plan","word":"Project manager","text":"The person who keeps a project on time and on budget, trackin' who does what and by when.","also":["project managers"]},{"id":"roadmap","g":"plan","word":"Roadmap","text":"A rough plan o' what be comin' over the next months, in order. It shows direction, not exact dates, and changes as ye learn.","also":["roadmaps"]},{"id":"milestone","g":"plan","word":"Milestone","text":"A point in a project worth markin', like “first version live” or “100 users”.","also":["milestones"]},{"id":"mvp","g":"plan","word":"Minimum viable product (MVP)","text":"The smallest version o' a product that be still useful to real folk, so ye can learn from 'em early.","also":["MVP","MVPs","minimum viable product"]},{"id":"requirement","g":"plan","word":"Requirement","text":"Somethin' the finished product must do or be.","also":["requirements"],"noTip":1},{"id":"scope","g":"plan","word":"Scope","text":"What be included in the work and, just as important, what be not.","also":["in scope","out of scope"]},{"id":"scopecreep","g":"plan","word":"Scope creep","text":"When more and more gets added to the work bit by bit, without anyone agreein' on the extra time or cost, so it never quite finishes.","also":["feature creep"]},{"id":"feature","g":"plan","word":"Feature","text":"One thing the product can do for folk, like “reset yer password”.","also":["features"],"noTip":1},{"id":"epic","g":"plan","word":"Epic","text":"A big piece o' work, too large for one go, so it be split into smaller cards.","also":["epics"]},{"id":"story","g":"plan","word":"User story","text":"A small piece o' work written from the user’s side: “As a shopper, I want to save me basket, so I can finish later.” It starts a conversation about what to build.","also":["user stories"]},{"id":"ac","g":"plan","word":"Acceptance criteria (AC)","text":"The checks one card must pass to count as done, agreed before work starts, like “the basket be still there after I log out and back in”.","also":["acceptance criteria"]},{"id":"task","g":"plan","word":"Task","text":"A single job to be done, often one small step o' a bigger story.","also":["tasks"],"noTip":1},{"id":"ticket","g":"plan","word":"Ticket","text":"Another word for a card: one piece o' work or one request, tracked from start to finish.","also":["tickets"]},{"id":"priority","g":"plan","word":"Priority","text":"How important or urgent somethin' be compared with everythin' else, so the most important work goes first.","also":["priorities"],"noTip":1},{"id":"prioritise","g":"plan","word":"Prioritisation","text":"Puttin' work in order o' importance. A common way be MoSCoW: Must have, Should have, Could have, Won’t have this time.","also":["MoSCoW"]},{"id":"estimate","g":"plan","word":"Estimate","text":"A best guess at how big or how long a piece o' work be. It be a guess, not a promise.","also":["estimates","estimation"],"noTip":1},{"id":"storypoints","g":"plan","word":"Story points","text":"A way o' guessin' the size o' work by comparin' cards with each other (“about twice as big as that one”) rather than in hours. They aren’t for comparin' crews.","also":["story point"]},{"id":"tshirt","g":"plan","word":"T-shirt sizing","text":"Guessin' the size o' work as S, M, L or XL. Quick and good enough for early plannin'.","also":["t-shirt sizes"]},{"id":"poker","g":"plan","word":"Plannin' poker","text":"A game for estimatin': every hand shows a size card at the same time, then the highest and lowest explain why.","also":["Scrum poker"]},{"id":"dependency","g":"plan","word":"Dependency","text":"When one piece o' work can’t start or finish until another one does.","also":["dependencies"]},{"id":"blocker","g":"plan","word":"Blocker","text":"Anythin' stoppin' work from movin' forward right now, like a missin' answer or a broken tool.","also":["blockers"]},{"id":"deadline","g":"plan","word":"Deadline","text":"The date somethin' must be finished by.","also":["deadlines"],"noTip":1},{"id":"deliverable","g":"plan","word":"Deliverable","text":"Somethin' concrete the work produces and hands over, like a workin' page or a report.","also":["deliverables"]},{"id":"forecast","g":"plan","word":"Forecast","text":"A prediction o' what be likely to happen, like when the work will be done, based on what ye know so far.","also":["forecasts"],"noTip":1},{"id":"metric","g":"plan","word":"Metric","text":"Anythin' ye measure and track over time, like page visits or how long a fix takes.","also":["metrics"]},{"id":"feedback","g":"plan","word":"Feedback","text":"What folk tell ye about yer work, good and bad. Gettin' it early and often be the heart o' Agile.","noTip":1},{"id":"backlog","g":"agile","word":"Backlog","text":"The waitin' list o' ideas and work not planned in yet, with the most important at the top. Nothin' there gets worked on until it moves to Yet to do."},{"id":"sprint","g":"agile","word":"Sprint","text":"A short, fixed stretch o' work (often one or two weeks, never more than a month) with a goal and an agreed set o' cards to finish.","also":["sprints"]},{"id":"standup","g":"agile","word":"Stand-up","text":"A quick daily check-in: what each crew member did, what they do next, and what be stoppin' 'em. In Scrum it be called the daily scrum.","also":["standup","stand-ups","daily scrum","daily stand-up"]},{"id":"kanban","g":"agile","word":"Kanban","text":"A way o' workin' where cards move across a board’s columns (like Yet to do, In progress, Done) and the crew limits how much be in progress at once, so work keeps flowin'."},{"id":"wip","g":"agile","word":"WIP limit","text":"WIP be short for work in progress. A WIP limit be the most cards a column should hold at once, so the crew finishes things before startin' more.","also":["WIP"]},{"id":"dod","g":"agile","word":"Definition o' Done","text":"The crew’s short checklist o' what “finished” means, like tested and explained, afore a card be handed to ye. Its twin, the Definition o' Ready, says when a card be clear enough to start.","also":["Definition of Ready","DoD","DoR"]},{"id":"retro","g":"agile","word":"Retro","text":"A regular look back at how the crew works, to agree on one or two things to do better next time. Short for retrospective. In AI-gile a retro suggests a change to the crew’s ways o' workin', and ye say Go or Not yet.","also":["retros","retrospective","retrospectives"]},{"id":"swarm","g":"agile","word":"Swarm","text":"All hands on deck: many folk drop other work to fix one urgent thing together until it be sorted. In AI-gile every crew helps on one project, and other projects wait meanwhile.","also":["swarming","all hands"]},{"id":"scrummaster","g":"agile","word":"Scrum Master","text":"In Scrum, the person who helps the crew work well: clears what blocks 'em, keeps meetings on track and coaches good habits, without bossin' anyone. In AI-gile the Lead Scrum Master spots stuck cards, nudges the crews and reminds ye o' what be waitin', across every project.","also":["Scrum captain","Lead Scrum Master"]},{"id":"agile","g":"agile","word":"Agile","text":"A way o' workin' in small steps: build a little, show real results often, learn from what folk say and change the plan as ye go, instead o' plannin' everythin' up front.","also":["Agile development","agile ways of working"]},{"id":"manifesto","g":"agile","word":"Agile Manifesto","text":"A short statement written in 2001 by software makers. It puts folk, workin' results, close work with customers and respondin' to change ahead o' heavy plans and paperwork.","also":["Manifesto for Agile Software Development"]},{"id":"waterfall","g":"agile","word":"Waterfall","text":"The older way o' workin': plan everythin', then build it all, then test it all, one stage after another. Changes late on be hard and costly.","also":["waterfall model"]},{"id":"iteration","g":"agile","word":"Iteration","text":"One round o' buildin' somethin', checkin' it and improvin' it. Agile work be a chain o' these, and a sprint be one kind.","also":["iterations"]},{"id":"increment","g":"agile","word":"Increment","text":"A new workin' piece added to the product in a sprint or round o' work, which fits with what was already there.","also":["increments"]},{"id":"scrum","g":"agile","word":"Scrum","text":"A popular Agile way o' workin': a small crew works in short sprints towards a goal, with set roles and a few regular meetings to plan, check and improve."},{"id":"scrumteam","g":"agile","word":"Scrum team","text":"The small crew that does the work in Scrum: a product owner, a Scrum Master and the developers.","also":["Scrum teams"]},{"id":"ceremonies","g":"agile","word":"Scrum events","text":"The regular meetings in Scrum: sprint plannin', the daily scrum, the sprint review and the retro. Many folk call 'em ceremonies.","also":["ceremonies","Scrum ceremonies"]},{"id":"sprintplan","g":"agile","word":"Sprint planning","text":"The meetin' at the start o' a sprint where the crew agrees why the sprint matters, which cards to take on and how to start.","also":["planning meeting"]},{"id":"sprintgoal","g":"agile","word":"Sprint goal","text":"One sentence sayin' what a sprint be for. Small tasks can change along the way, as long as the goal be met.","also":["sprint goals"]},{"id":"sprintbacklog","g":"agile","word":"Sprint backlog","text":"The cards picked for the current sprint, with the crew’s plan for doin' 'em.","also":["sprint backlogs"]},{"id":"productbacklog","g":"agile","word":"Product backlog","text":"The full ordered list o' everythin' that might be built for the product, most important at the top. It keeps changin' as ye learn.","also":["product backlogs"]},{"id":"productgoal","g":"agile","word":"Product goal","text":"The bigger result the product be workin' towards, which helps the crew choose what to do next.","also":["product goals"]},{"id":"refinement","g":"agile","word":"Backlog refinement","text":"Regularly goin' through the backlog to tidy, split, order and add detail to cards, so they be ready to pick up. Also called backlog groomin'.","also":["backlog grooming","refinement"]},{"id":"sprintreview","g":"agile","word":"Sprint review","text":"A meetin' at the end o' a sprint where the crew shows what it finished and hears what folk think, to decide what comes next.","also":["sprint reviews"]},{"id":"demo","g":"agile","word":"Demo","text":"Showin' finished work workin', live, to the folk who asked for it.","also":["demos"],"noTip":1},{"id":"timebox","g":"agile","word":"Timebox","text":"A fixed amount o' time for somethin'. When it runs out ye stop, even if not everythin' be done.","also":["timeboxed","timeboxes"]},{"id":"velocity","g":"agile","word":"Velocity","text":"How much work a crew usually finishes in a sprint, used to plan how much to take on next time. It be not a score for how hard folk work.","also":["team velocity"]},{"id":"capacity","g":"agile","word":"Capacity","text":"How much work the crew can take on in a period, after shore leave and other jobs.","noTip":1},{"id":"burndown","g":"agile","word":"Burndown chart","text":"A chart o' the work left in a sprint goin' down day by day. If the line stays flat, somethin' be stuck.","also":["burndown","burn-down chart"]},{"id":"burnup","g":"agile","word":"Burnup chart","text":"A chart o' finished work goin' up over time, next to the total planned, so ye can see when ye will get there.","also":["burnup","burn-up chart"]},{"id":"kanbanboard","g":"agile","word":"Kanban board","text":"The board itself: a column for each stage o' the work, with cards movin' across.","also":["Kanban boards"]},{"id":"pullsys","g":"agile","word":"Pull system","text":"A way o' workin' where new work only starts when someone has room to take it on, rather than bein' pushed onto a full plate.","also":["pull-based"]},{"id":"flow","g":"agile","word":"Flow","text":"How smoothly work moves across the board. Good flow means cards keep movin' rather than pilin' up.","also":["flow of work"],"noTip":1},{"id":"leadtime","g":"agile","word":"Lead time","text":"How long it takes from someone askin' for somethin' to it bein' finished.","also":["lead times"]},{"id":"cycletime","g":"agile","word":"Cycle time","text":"How long a card takes from when work really starts on it to when it be finished.","also":["cycle times"]},{"id":"throughput","g":"agile","word":"Throughput","text":"How many cards get finished in a week, or in any set time.","also":["throughput rate"]},{"id":"bottleneck","g":"agile","word":"Bottleneck","text":"The one stage where work piles up and slows everythin' behind it, like the narrow neck o' a bottle.","also":["bottlenecks"]},{"id":"swimlane","g":"agile","word":"Swimlane","text":"A row across the board that groups cards o' one kind, such as urgent work or one crew’s cards.","also":["swimlanes","swim lane"]},{"id":"lean","g":"agile","word":"Lean","text":"A way o' workin' that cuts out waste (anythin' that doesn’t help the customer) and keeps work flowin'."},{"id":"waste","g":"agile","word":"Waste","text":"In Lean, anythin' that takes effort but doesn’t help the customer, like waitin', rework or buildin' things nobody uses.","noTip":1},{"id":"kaizen","g":"agile","word":"Continuous improvement","text":"Gettin' a little better all the time through small regular changes, then checkin' they helped. Retros be one way to do it. Also called kaizen.","also":["kaizen"]},{"id":"selforg","g":"agile","word":"Self-organising team","text":"A crew that decides for itself how to do the work, rather than bein' told step by step.","also":["self-organising","self-managing team"]},{"id":"crossfunc","g":"agile","word":"Cross-functional team","text":"A crew that has all the skills it needs to finish the work itself, like design, buildin' and testin'.","also":["cross-functional"]},{"id":"spike","g":"agile","word":"Spike","text":"A short, timeboxed bit o' research to answer a question before committin' to the real work.","also":["spikes"]},{"id":"rework","g":"agile","word":"Rework","text":"Doin' work again because it wasn’t right the first time.","also":["reworked"]},{"id":"safe","g":"agile","word":"Scaled Agile (SAFe)","text":"Ways o' usin' Agile across many crews in a big organisation. SAFe (the Scaled Agile Framework) be one well known example.","also":["scaled Agile"]},{"id":"repo","g":"build","word":"Repo","text":"The project’s folder o' code with its full history o' commits. It can live on yer computer, on GitHub, or both.","also":["repository"]},{"id":"branch","g":"build","word":"Branch","text":"A separate line of work in the code, so changes can be made without touchin' the main version.","also":["branches"]},{"id":"commit","g":"build","word":"Commit","text":"A saved snapshot of the code, with a short note of what changed. Ye can always go back to one.","also":["commits"]},{"id":"push","g":"build","word":"Push","text":"Sendin' yer saved snapshots (commits) from this computer to the shared copy online, such as GitHub, so they be backed up and others can get 'em."},{"id":"merge","g":"build","word":"Merge","text":"Joinin' the changes from one branch into another, usually back into the main version."},{"id":"pr","g":"build","word":"Pull request","text":"Askin' for a branch’s changes to be checked and merged into the main version. Some sites call it a merge request.","also":["PR","PRs","merge request"]},{"id":"refactor","g":"build","word":"Refactor","text":"Tidyin' the code without changin' what it does: smaller files, clearer names, less repetition."},{"id":"bug","g":"build","word":"Bug","text":"Somethin' that doesn’t work the way it should.","also":["bugs"]},{"id":"peerreview","g":"build","word":"Peer review","text":"A second pair o' eyes: someone other than the author checks the work before it reaches ye, so fewer mistakes get through. In AI-gile another AI checks each card.","also":["code review"]},{"id":"code","g":"build","word":"Code","text":"The written instructions that tell a computer what to do. Also called source code.","also":["source code"],"noTip":1},{"id":"proglang","g":"build","word":"Programming language","text":"A language for writin' code, such as JavaScript, Python or Java. Different ones suit different jobs.","also":["programming languages"]},{"id":"developer","g":"build","word":"Developer (dev)","text":"Someone who writes and changes code. Also called a programmer or software engineer.","also":["developer","developers","programmer","programmers","software engineer"]},{"id":"software","g":"build","word":"Software","text":"Programs that run on computers and phones, as opposed to the machines themselves (the hardware).","noTip":1},{"id":"app","g":"build","word":"App","text":"Short for application: a program folk use to get somethin' done, on a phone, a computer or in a web browser.","also":["apps","application","applications"],"noTip":1},{"id":"webapp","g":"build","word":"Web app","text":"An app that runs in a web browser, so there be nothin' to install.","also":["web apps","web application"]},{"id":"frontend","g":"build","word":"Front end","text":"The part o' an app ye see and click on: the screens, buttons and words, often in yer browser.","also":["front-end","frontend"]},{"id":"backend","g":"build","word":"Back end","text":"The behind-the-scenes part o' an app that keeps the data and does the work when ye click somethin', like checkin' yer password.","also":["back-end","backend"]},{"id":"fullstack","g":"build","word":"Full stack","text":"Workin' on both the front end and the back end.","also":["full-stack"]},{"id":"ui","g":"build","word":"User interface (UI)","text":"What a person sees and uses on screen: layout, buttons, menus and text.","also":["UI","user interface"]},{"id":"ux","g":"build","word":"User experience (UX)","text":"How it feels to use somethin': easy, clear and pleasant, or confusin' and slow.","also":["UX","user experience"]},{"id":"accessibility","g":"build","word":"Accessibility (a11y)","text":"Makin' things usable by everyone, includin' folk who can’t see well, can’t use a mouse or use a screen reader.","also":["a11y"]},{"id":"responsive","g":"build","word":"Responsive design","text":"Makin' pages fit and work well on any screen size, from a phone to a big monitor."},{"id":"designsys","g":"build","word":"Design system","text":"A shared kit o' colours, fonts, buttons and rules, so every screen looks and behaves the same way.","also":["design systems"]},{"id":"architecture","g":"build","word":"Architecture","text":"The overall shape o' a system: what the main parts be and how they talk to each other."},{"id":"database","g":"build","word":"Database (DB)","text":"An organised store o' information, like a very powerful spreadsheet that the app can read and change.","also":["database","databases","DB"]},{"id":"schema","g":"build","word":"Database schema","text":"The layout o' a database: which tables o' information it has and what goes in each.","also":["schema"]},{"id":"sql","g":"build","word":"SQL","text":"Short for structured query language: the language used to ask many databases for information or to change it.","also":["Structured Query Language"]},{"id":"data","g":"build","word":"Data","text":"Information kept by a computer, like names, orders or settings.","also":["dataset","datasets"],"noTip":1},{"id":"server","g":"build","word":"Server","text":"A computer that be always on and answers requests from other computers, like sendin' a web page when ye visit it.","also":["servers"]},{"id":"client","g":"build","word":"Client","text":"The side that asks for somethin', usually yer browser or app, talkin' to a server. In business it also just means a customer.","also":["clients"],"noTip":1},{"id":"api","g":"build","word":"API","text":"Short for application programming interface: a set menu o' requests one program can make to another, like askin' a weather service for today’s forecast.","also":["APIs","application programming interface"]},{"id":"endpoint","g":"build","word":"Endpoint","text":"One item on an API’s menu: a web address a program can call to get or send somethin'.","also":["endpoints"]},{"id":"integration","g":"build","word":"Integration","text":"Connectin' two systems so they work together, like yer shop sendin' orders to yer accounts software.","also":["integrations"]},{"id":"webhook","g":"build","word":"Webhook","text":"A message one system sends to another by itself the moment somethin' happens, like “payment received”.","also":["webhooks"]},{"id":"library","g":"build","word":"Library","text":"Ready-made code someone else wrote that ye can reuse instead o' writin' it yerself.","also":["libraries"],"noTip":1},{"id":"framework","g":"build","word":"Framework","text":"A ready-made structure for buildin' an app that decides much o' how the code be laid out, like a ship's frame ye fill in.","also":["frameworks"]},{"id":"sdk","g":"build","word":"Software development kit (SDK)","text":"A chest o' tools, code and examples for buildin' software for one platform or service.","also":["SDK","SDKs"]},{"id":"softdep","g":"build","word":"Software dependency","text":"A library or tool yer code needs to work. Keepin' 'em up to date matters for safety.","also":["software dependencies"]},{"id":"package","g":"build","word":"Package","text":"A bundle o' ready-made code ye can install and use in a project.","also":["packages"],"noTip":1},{"id":"pkgmgr","g":"build","word":"Package manager","text":"A tool that fetches and updates the packages yer code depends on. npm be a common one.","also":["package managers","npm"]},{"id":"git","g":"build","word":"Git","text":"The most widely used tool for keepin' the history o' code changes, as commits and branches."},{"id":"github","g":"build","word":"GitHub","text":"A website that keeps Git repos online, so crews can share code, review changes and track work."},{"id":"vcs","g":"build","word":"Version control","text":"Keepin' a full history o' every change to the files, so ye can see who changed what and go back if needed. Git does this.","also":["source control","version control system"]},{"id":"clone","g":"build","word":"Clone","text":"Makin' yer own full copy o' a repo, with its history, on yer computer.","also":["cloned","cloning"]},{"id":"pull","g":"build","word":"Pull","text":"Fetchin' the latest commits from the shared copy (like GitHub) onto yer computer. The opposite o' push.","also":["git pull"],"noTip":1},{"id":"mainbranch","g":"build","word":"Main branch","text":"The official version o' the code that everyone works from, often called main or master.","also":["master branch"]},{"id":"conflict","g":"build","word":"Merge conflict","text":"When two changes touch the same lines in different ways, so the computer can’t join 'em and a person has to choose.","also":["merge conflicts"]},{"id":"diff","g":"build","word":"Diff","text":"A view showin' exactly what changed between two versions: lines added and lines taken away.","also":["diffs"]},{"id":"fork","g":"build","word":"Fork","text":"Yer own copy o' someone else’s repo, which ye can change without affectin' theirs.","also":["forks","forked"]},{"id":"script","g":"build","word":"Script","text":"A short program that does one job by itself, like tidyin' files or startin' the app.","also":["scripts"],"noTip":1},{"id":"build","g":"build","word":"Build","text":"Turnin' the code into somethin' ready to run, or the ready-to-run result itself.","also":["builds"],"noTip":1},{"id":"compile","g":"build","word":"Compile","text":"Translatin' code folk wrote into a form the computer can run directly.","also":["compiler"]},{"id":"cli","g":"build","word":"Command line (CLI)","text":"A text window where ye type instructions for the computer instead o' clickin'. Also called the terminal.","also":["command line","command-line","CLI","terminal"]},{"id":"config","g":"build","word":"Configuration (config)","text":"The settings that control how software behaves, kept apart from the code so they be easy to change.","also":["config","configuration"],"noTip":1},{"id":"envvar","g":"build","word":"Environment variable","text":"A setting handed to a program when it starts, often used for addresses or passwords so they aren’t written into the code.","also":["environment variables","env var"]},{"id":"debugging","g":"build","word":"Debugging","text":"Huntin' down why somethin' isn’t workin', and fixin' it.","also":["debug","debugged"]},{"id":"pairing","g":"build","word":"Pair programming","text":"Two folk (or a person and an AI) workin' on the same code together, one typin' and one checkin'.","also":["pairing"]},{"id":"docs","g":"build","word":"Documentation (docs)","text":"Written explanations o' how somethin' works or how to use it.","also":["documentation","docs"],"noTip":1},{"id":"readme","g":"build","word":"README","text":"The first file to read in a repo: what the project be and how to get it runnin'.","also":["READMEs"]},{"id":"legacy","g":"build","word":"Legacy system","text":"An older system still in use that be hard to change, often because few folk still understand it.","also":["legacy systems","legacy code"]},{"id":"techdebt","g":"build","word":"Technical debt","text":"Shortcuts that save time now but make later changes slower, like a loan that builds up interest. Refactorin' pays it down.","also":["tech debt"]},{"id":"test","g":"test","word":"Test","text":"A check that somethin' works the way it should. Some tests the computer runs by itself every time the code changes; others be ye tryin' a finished card before ye accept it.","also":["tests"],"noTip":1},{"id":"qa","g":"test","word":"QA","text":"Short for quality assurance: everythin' done to make sure work be right before it goes live. In AI-gile that means the automatic checks: when QA be red, somethin' failed, and it can’t go live until that be fixed.","also":["quality checks","quality assurance"]},{"id":"testpile","g":"test","word":"Test pile","text":"The finished cards waitin' fer ye to try, one after another. Accept one or send it back with a note, and the next one comes up.","also":["test piles"]},{"id":"autotest","g":"test","word":"Automated test","text":"A check the computer runs by itself every time the code changes, to catch mistakes early.","also":["automated tests","automatic tests"]},{"id":"manualtest","g":"test","word":"Manual test","text":"A person tryin' the work by hand to see if it behaves as it should.","also":["manual tests","manual testing"]},{"id":"unittest","g":"test","word":"Unit test","text":"A small automatic check o' one tiny piece o' code on its own.","also":["unit tests"]},{"id":"integtest","g":"test","word":"Integration test","text":"A check that several parts work properly together, not just one at a time.","also":["integration tests"]},{"id":"endtoend","g":"test","word":"End-to-end test (E2E)","text":"A test that acts like a real user from start to finish, such as signin' up, buyin' and payin'.","also":["E2E","end-to-end tests"]},{"id":"uat","g":"test","word":"User acceptance testing (UAT)","text":"The folk who asked for the work try it themselves and say whether it does what they need. AI-gile’s test pile be its version o' this.","also":["UAT","acceptance testing"]},{"id":"regression","g":"test","word":"Regression","text":"Somethin' that used to work but broke after a change. Regression tests check that the old things still work.","also":["regressions","regression test","regression tests","regression testing"]},{"id":"smoke","g":"test","word":"Smoke test","text":"A very quick check that the main things work at all, for example right after a change goes live. If it fails, stop and look.","also":["smoke tests"]},{"id":"exploratory","g":"test","word":"Exploratory testing","text":"Tryin' the product freely and pokin' at it in different ways, to find problems that planned checks would miss.","also":["exploratory test","exploratory tests"]},{"id":"testcase","g":"test","word":"Test case","text":"One written scenario to try: the steps, and what should happen.","also":["test cases"]},{"id":"coverage","g":"test","word":"Test coverage","text":"How much o' the code be checked by automatic tests. More be usually safer, but high coverage alone doesn’t prove it works well.","also":["code coverage"]},{"id":"testdata","g":"test","word":"Test data","text":"Made-up example information used while testin', so no real person’s private details be exposed.","also":["test fixtures"]},{"id":"edgecase","g":"test","word":"Edge case","text":"An unusual situation at the limits, like an empty form or a name with an apostrophe, where things often break.","also":["edge cases"]},{"id":"happypath","g":"test","word":"Happy path","text":"The normal route where everythin' goes right. Good testin' also tries the unhappy paths."},{"id":"perftest","g":"test","word":"Performance testing","text":"Checkin' how fast somethin' be and how well it copes under strain.","also":["performance test","performance tests"]},{"id":"loadtest","g":"test","word":"Load testing","text":"Checkin' how a system copes when lots o' folk use it at once.","also":["load test","load tests"]},{"id":"sectest","g":"test","word":"Security testing","text":"Lookin' for weaknesses that could let someone misuse a system or see what they shouldn’t.","also":["security test","security tests"]},{"id":"accesstest","g":"test","word":"Accessibility testing","text":"Checkin' that folk with different abilities can use the product, includin' with a screen reader or only a keyboard.","also":["accessibility test"]},{"id":"linting","g":"test","word":"Linting","text":"An automatic check that spots likely mistakes and messy style in code, like a spellin' checker for programs.","also":["linter","lint"]},{"id":"static","g":"test","word":"Static analysis","text":"Checkin' code for problems by readin' it automatically, without runnin' it.","also":["static code analysis"]},{"id":"flaky","g":"test","word":"Flaky test","text":"A test that sometimes passes and sometimes fails for no clear reason, so it can’t be fully trusted.","also":["flaky tests"]},{"id":"repro","g":"test","word":"Reproduce (repro)","text":"Makin' a bug happen again on purpose by followin' the same steps, so it can be studied and fixed. Writin' those steps down be the most useful part o' a bug report.","also":["repro","reproduce","steps to reproduce"]},{"id":"severity","g":"test","word":"Severity","text":"How bad a problem’s effect be, from a small annoyance to everythin' stoppin'.","also":["severity level"]},{"id":"deploy","g":"change","word":"Deploy","text":"Copyin' a new version o' the software onto the computers that run it, such as a test copy or the live service."},{"id":"release","g":"change","word":"Release","text":"A named haul o' finished work that goes live together, with short notes on what changed. 🚀 Releases writes the notes from the done cards.","also":["releases"]},{"id":"rollback","g":"change","word":"Roll back","text":"Goin' back to the last version that worked when a new one causes trouble. In AI-gile, Roll back gathers the undo steps written on each change into one checklist.","also":["rollback","roll-back","rolled back"]},{"id":"live","g":"change","word":"Live","text":"The real version that folk use, as opposed to a copy fer tryin' things out. Developers also call it production.","also":["production"],"noTip":1},{"id":"change","g":"change","word":"Change","text":"A planned change to somethin' folk rely on, written down first: what, why, the risk, when, and how to undo it. Start one with 🔀 Raise a change.","also":["change request","change requests"],"noTip":1},{"id":"risk","g":"change","word":"Risk","text":"Somethin' that could go wrong, scored on how likely and how bad it would be. ⚠️ Risks keeps 'em in one list, highest score first, each with a date to look again.","also":["risks","risk register"]},{"id":"chgwin","g":"change","word":"Change window","text":"The times when changes may go live, such as a calm Tuesday evenin'. Outside a window a change card can’t be finished, unless it be an emergency.","also":["change windows"]},{"id":"gonogo","g":"change","word":"Go / no go","text":"A last check just before a change goes live: each person who has to approve says Go or No go. It only goes ahead when everyone says Go.","also":["go/no go","go-no-go"]},{"id":"approval","g":"change","word":"Approval","text":"Waitin' fer an aye afore work starts. A card a friend raises, or a change, waits in ✅ Approvals till ye approve or decline it.","also":["approvals"]},{"id":"quiettime","g":"change","word":"Quiet time","text":"A stretch o' time, like durin' a live stream, a demo or overnight, when nothin' goes live. The crews keep workin' and testin', but goin' live waits until it ends. Elsewhere it be called a change freeze.","also":["quiet times","change freeze"]},{"id":"devops","g":"change","word":"DevOps","text":"A way o' workin' where the folk who build software and the folk who run it work as one crew, with lots o' automation, so changes go live often and safely."},{"id":"cicd","g":"change","word":"CI/CD (continuous integration and delivery)","text":"Everyone’s changes be joined into the main version often and checked automatically each time (continuous integration), so the software be always ready to go live at the press o' a button (continuous delivery).","also":["CI/CD","CI","CD","continuous integration","continuous delivery"]},{"id":"contdeploy","g":"change","word":"Continuous deployment","text":"One step further than continuous delivery: every change that passes the checks goes live by itself, with no button to press.","also":["continuous deployments"]},{"id":"pipeline","g":"change","word":"Pipeline","text":"The automatic series o' steps a change goes through on its way to live, like build, test, then deploy.","also":["pipelines"]},{"id":"environment","g":"change","word":"Environment","text":"One separate copy o' the system for one purpose, such as one to build in, one to test in and the live one.","also":["environments"],"noTip":1},{"id":"devenv","g":"change","word":"Development environment","text":"The copy a developer works in, often on their own computer, where breakin' things harms nobody.","also":["dev environment"]},{"id":"testenv","g":"change","word":"Test environment","text":"A separate copy o' the system used just for testin', so the real service isn’t touched.","also":["test environments"]},{"id":"staging","g":"change","word":"Staging","text":"A last copy set up just like live, for a final check before a change goes live.","also":["staging environment"]},{"id":"artifact","g":"change","word":"Build artifact","text":"The file or bundle a build produces, ready to be stored, checked or put live.","also":["build artifacts"]},{"id":"hotfix","g":"change","word":"Hotfix","text":"An urgent fix put live quickly, outside the normal plan, because somethin' important be broken.","also":["hotfixes"]},{"id":"patch","g":"change","word":"Patch","text":"A small update that fixes a bug or closes a security hole. Applyin' security patches quickly matters.","also":["patches","security patch","security patches"]},{"id":"version","g":"change","word":"Version number","text":"A label like 2.4.1 that says which release ye have. Often the first number changes for big changes and the last for small fixes.","also":["version numbers","semantic versioning"]},{"id":"relnotes","g":"change","word":"Release notes","text":"A short plain list o' what changed in a release, for the folk who use it, includin' fixes and known limits. Also called a changelog.","also":["changelog","change log"]},{"id":"flag","g":"change","word":"Feature flag","text":"An on and off switch for a feature, so new work can go live hidden and be turned on (or off again) without a new release.","also":["feature flags","feature toggle","feature toggles"]},{"id":"rollfwd","g":"change","word":"Roll forward","text":"Fixin' a bad release by quickly puttin' out a new, corrected version instead o' goin' back to the old one.","also":["rolling forward","rolled forward"]},{"id":"canary","g":"change","word":"Canary release","text":"Puttin' a change live for a small group first, and for everyone only once it looks fine. Named after the canaries miners took underground as an early warnin'.","also":["canary releases","canary"]},{"id":"bluegreen","g":"change","word":"Blue-green deployment","text":"Keepin' two copies o' the live system and switchin' folk over to the new one in one go, so ye can switch straight back if it goes wrong.","also":["blue-green","blue green deployment"]},{"id":"zerodown","g":"change","word":"Zero-downtime deployment","text":"Puttin' a new version live without the service ever stoppin' for its users.","also":["zero downtime","zero-downtime"]},{"id":"chgenable","g":"change","word":"Change enablement","text":"Helpin' changes succeed: weighin' the risk, gettin' the right approval and pickin' a good time. Also called change management.","also":["change management"]},{"id":"cab","g":"change","word":"Change advisory board (CAB)","text":"A group that looks over important changes and agrees whether and when they may go ahead.","also":["CAB"]},{"id":"stdchange","g":"change","word":"Standard change","text":"A low-risk change done the same tried and tested way each time, so it be approved in advance.","also":["standard changes"]},{"id":"normchange","g":"change","word":"Normal change","text":"A change that needs to be checked and approved before it goes ahead.","also":["normal changes"]},{"id":"emergchange","g":"change","word":"Emergency change","text":"A change that must happen right away to fix or prevent serious trouble, with a quicker approval to match.","also":["emergency changes"]},{"id":"automation","g":"change","word":"Automation","text":"Gettin' the computer to do a repeated job by itself, so it be quicker and done the same way every time.","also":["automated"],"noTip":1},{"id":"infra","g":"change","word":"Infrastructure","text":"The machines, networks and services that software runs on.","also":["infra"]},{"id":"iac","g":"change","word":"Infrastructure as code (IaC)","text":"Describin' yer servers and settings in files kept with the code, so they can be rebuilt exactly the same way every time.","also":["IaC"]},{"id":"cloud","g":"change","word":"Cloud","text":"Rentin' computers, storage and services from a big provider over the internet, instead o' ownin' the machines yerself.","also":["the cloud","cloud computing"]},{"id":"provider","g":"change","word":"Cloud provider","text":"A company that rents out computin' over the internet, such as Amazon Web Services (AWS), Microsoft Azure or Google Cloud.","also":["cloud providers"]},{"id":"hosting","g":"change","word":"Hosting","text":"Where yer app or website lives and runs so folk can reach it, usually rented from a company."},{"id":"domain","g":"change","word":"Domain name","text":"The web address folk type, like example.com. Ye rent it by the year, so it must be renewed.","also":["domain names","domain"]},{"id":"dns","g":"change","word":"DNS","text":"Short for domain name system: the internet’s address book, which turns a name like example.com into the address o' the right computer.","also":["domain name system"]},{"id":"container","g":"change","word":"Container","text":"A sealed package holdin' an app and everythin' it needs, so it runs the same on any computer. Docker be the best known tool.","also":["containers","Docker"],"noTip":1},{"id":"vm","g":"change","word":"Virtual machine (VM)","text":"A pretend computer runnin' inside a real one, so one big machine can act as many.","also":["VM","VMs","virtual machines"]},{"id":"serverless","g":"change","word":"Serverless","text":"Runnin' code without lookin' after any servers yerself: the provider runs it when needed and ye pay for what ye use."},{"id":"lb","g":"change","word":"Load balancer","text":"Somethin' that spreads visitors across several servers, so no single one gets overwhelmed.","also":["load balancers"]},{"id":"cache","g":"change","word":"Cache","text":"A handy store o' recent results kept close by, so the same thing doesn’t have to be fetched or worked out again. Clearin' it can fix pages that look out o' date.","also":["caches","caching","cached"]},{"id":"cdn","g":"change","word":"Content delivery network (CDN)","text":"A worldwide set o' servers holdin' copies o' yer pages and pictures near yer visitors, so they load quickly.","also":["CDN"]},{"id":"migration","g":"change","word":"Migration","text":"Movin' data or systems from an old setup to a new one, or carefully changin' how a database be laid out.","also":["migrations","database migration"]},{"id":"service","g":"run","word":"Service","text":"Somethin' ye built that folk rely on, like a website or an app, looked after so it keeps workin'. Tick “This project be a service” and say what it offers, who uses it and who be on call.","also":["services"]},{"id":"uptimepct","g":"run","word":"Uptime","text":"How much o' the time a service be workin', usually as a percentage. 99.9% still allows about 43 minutes down a month.","also":["uptime percentage"]},{"id":"uptime","g":"run","word":"Uptime check","text":"An automatic check, every few minutes, that yer service still answers. If it fails several times in a row, AI-gile opens a storm card by itself.","also":["uptime checks"]},{"id":"statuspage","g":"run","word":"Status page","text":"A public page that shows whether a service be workin' (green, orange or red) with the latest word, so the folk who use it can check instead o' askin'.","also":["status pages"]},{"id":"desk","g":"run","word":"Service desk","text":"Where questions and reports from the folk usin' yer service come in. AI-gile sorts each one into a request, an incident or an idea, and says so when it looks like somethin' already reported.","also":["service desks","help desk","helpdesk"]},{"id":"svcrequest","g":"run","word":"Service request","text":"Someone askin' fer somethin' ordinary, like a new account or a bit o' help, instead o' reportin' that somethin' be broken. It waits its turn; an incident goes first.","also":["service requests"]},{"id":"incident","g":"run","word":"Incident","text":"Somethin' that be broken or not workin' properly for the folk usin' it right now, like the website bein' down or very slow. A 🔥 incident card jumps the queue: gettin' it workin' again comes first.","also":["incidents","storm aboard","storms aboard"]},{"id":"major","g":"run","word":"Major incident","text":"A great storm: many folk hit, or doubloons or data at risk. One button puts every crew on it (all hands), wakes whoever be on call and asks fer a status update every 30 minutes.","also":["major incidents"]},{"id":"oncall","g":"run","word":"On call","text":"Bein' the one who answers when somethin' breaks, even at night. Each service has an on-call crew member who be woken first fer its storms.","also":["on-call"]},{"id":"replyby","g":"run","word":"Reply-by time","text":"How long a card may wait fer a first answer, fer example an hour fer a storm aboard. After that it gets a red clock, so nothin' be quietly forgotten. Also called a response target.","also":["reply-by times","response target","response targets"]},{"id":"postmortem","g":"run","word":"Post-mortem","text":"A short look back after a storm, the after-storm reckonin': what happened, what helped and what to change, without blamin' anyone. A storm card can’t be closed without one.","also":["post-mortems","postmortem","post-incident review","after-storm reckoning"]},{"id":"problem","g":"run","word":"Problem","text":"The hidden cause behind one or more storms. A 🧩 problem card groups storms that keep comin' back, so the cause be found and fixed fer good.","also":["problems"],"noTip":1},{"id":"rootcause","g":"run","word":"Root cause","text":"The real reason somethin' broke, not just what ye saw goin' wrong. Fix the root cause and the storm stops comin' back.","also":["root causes"]},{"id":"workaround","g":"run","word":"Workaround","text":"A way to keep the ship sailin' till the real fix be ready, like restartin' somethin' when it gets stuck. It be written on the problem card so nobody has to work it out again.","also":["workarounds"]},{"id":"knownerror","g":"run","word":"Known error","text":"A problem whose cause be understood but isn’t fixed yet, usually with a workaround written down. 🧩 Known errors lists 'em, so everyone uses the workaround instead o' diggin' again.","also":["known errors"]},{"id":"runbook","g":"run","word":"Runbook","text":"Step-by-step orders fer fixin' a known kind o' trouble, so it be done the same way, quick, every time. After a great storm the crew can propose one fer ye to OK.","also":["runbooks"]},{"id":"ci","g":"run","word":"Configuration item","text":"One thing yer service leans on, like a server, a domain, a certificate, a key or a supplier. 🗂️ Configuration items lists 'em per service, so ye can see what an incident hits and what needs renewin' or a backup.","also":["configuration items"]},{"id":"expiry","g":"run","word":"Expiry date","text":"The date somethin' stops workin' unless it be renewed, like a website’s security certificate or its web address. AI-gile watches these dates and makes one card to renew each one 30 days before, so nothin' stops by surprise.","also":["expiry dates","expiry","expiry watch"]},{"id":"backup","g":"run","word":"Backup","text":"A saved copy o' yer data from earlier, to fall back on if somethin' be lost or damaged. AI-gile makes a backup o' yer boards every day.","also":["backups","back-up","back-ups"]},{"id":"restore","g":"run","word":"Restore","text":"Puttin' data back from a backup. A backup only really counts once ye know it can be restored, so it be worth tryin' now and then.","also":["restored"]},{"id":"svcreview","g":"run","word":"Service review","text":"A look back at one month o' a service: incidents opened and fixed, how quick folk got an answer, uptime and tokens used. The Monthly review shows it fer each service.","also":["service reviews","monthly review","monthly reviews"]},{"id":"accessreview","g":"run","word":"Access review","text":"Checkin' every 90 days who can still get in: share links, friends’ roles and saved passwords and keys. Ye keep or remove each one, so old access doesn’t linger.","also":["access reviews"]},{"id":"improvements","g":"run","word":"Improvement list","text":"Everythin' the crew decided to get better at, in one place: retro suggestions, review actions and problem fixes, each with its status. Find it under 📈 Improvements.","also":["improvement lists","improvements"]},{"id":"tokencap","g":"run","word":"Token cap","text":"A monthly limit on the tokens a service’s agents may use. At 80% ye get a warnin'; at 100% their background work waits till next month or till ye raise the cap.","also":["token caps"]},{"id":"svcmgmt","g":"run","word":"Service management","text":"Everythin' involved in keepin' a service useful and workin' for the folk who rely on it, day after day."},{"id":"itil","g":"run","word":"ITIL","text":"A widely used guide to good service management, coverin' things like incidents, problems and changes. The name once stood for IT Infrastructure Library."},{"id":"itsm","g":"run","word":"IT service management (ITSM)","text":"Runnin' technology as a service for folk, with clear ways to handle requests, incidents, changes and improvements.","also":["ITSM"]},{"id":"managed","g":"run","word":"Managed service","text":"A service someone else runs and looks after for ye, under an agreement about how well it must work.","also":["managed services"]},{"id":"svcowner","g":"run","word":"Service owner","text":"The person who answers for a service as a whole: how well it works, what it costs and how it improves.","also":["service owners"]},{"id":"sla","g":"run","word":"Service level agreement (SLA)","text":"A written promise to customers about how well a service will work, like “up 99.9% o' the time” or “answered within an hour”, often with doubloons back if it be broken.","also":["SLA","SLAs","service level agreement"]},{"id":"slo","g":"run","word":"Service level objective (SLO)","text":"The crew’s own target for how well a service should work over a period, usually set a bit stricter than the SLA to be safe.","also":["SLO","SLOs"]},{"id":"sli","g":"run","word":"Service level indicator (SLI)","text":"The actual measurement ye check against a target, like the share o' visits that loaded fine.","also":["SLI","SLIs"]},{"id":"availability","g":"run","word":"Availability","text":"Whether folk can use a service when they need it, often measured as uptime.","also":["high availability"]},{"id":"downtime","g":"run","word":"Downtime","text":"Time when a service isn’t workin' or be switched off, planned or not.","also":["down time"]},{"id":"errorbudget","g":"run","word":"Error budget","text":"The small amount o' failure yer reliability target allows. While some be left ye can take risks with changes; once it be used up, ye slow down.","also":["error budgets"]},{"id":"outage","g":"run","word":"Outage","text":"A time when a service be down or badly broken for its users.","also":["outages"]},{"id":"degraded","g":"run","word":"Degraded","text":"Workin', but badly: slow, or with some parts not workin'.","also":["degraded service"]},{"id":"monitoring","g":"run","word":"Monitoring","text":"Watchin' a service automatically all the time, so problems be spotted, ideally before users notice."},{"id":"observability","g":"run","word":"Observability","text":"How well ye can tell what be goin' on inside a system from the outside, usin' its logs, numbers and traces.","also":["o11y"]},{"id":"log","g":"run","word":"Log","text":"A runnin' diary a program keeps o' what it be doin', used to work out what went wrong. Like a ship's log.","also":["logs","logging"],"noTip":1},{"id":"trace","g":"run","word":"Trace","text":"A record o' how one request travels through the different parts o' a system, step by step, showin' where it slowed down.","also":["traces","tracing"]},{"id":"latency","g":"run","word":"Latency","text":"How long somethin' takes to answer, like the wait between clickin' and the page appearin'."},{"id":"alert","g":"run","word":"Alert","text":"An automatic message that somethin' needs attention, like the website not answerin'.","also":["alerts","alerting"],"noTip":1},{"id":"alertfatigue","g":"run","word":"Alert fatigue","text":"When there be so many alerts that folk start ignorin' 'em, includin' the important ones.","also":["alarm fatigue"]},{"id":"dashboard","g":"run","word":"Dashboard","text":"A screen showin' the most important numbers and statuses at a glance.","also":["dashboards"],"noTip":1},{"id":"paging","g":"run","word":"Paging","text":"Urgently callin' or wakin' the on-call person about a problem.","also":["paged"]},{"id":"escalation","g":"run","word":"Escalation","text":"Bringin' in someone with more skill or authority when an issue can’t be sorted at the current level, or not fast enough.","also":["escalate","escalated"]},{"id":"triage","g":"run","word":"Triage","text":"Quickly sortin' incomin' issues by how urgent and important they be, so the worst gets handled first.","also":["triaged"]},{"id":"impact","g":"run","word":"Impact","text":"How much somethin' affects folk: how many, and how badly.","noTip":1},{"id":"urgency","g":"run","word":"Urgency","text":"How quickly somethin' needs to be dealt with. Impact and urgency together set the priority.","noTip":1},{"id":"plevels","g":"run","word":"Priority levels (P1, P2…)","text":"Labels for how urgent an issue be. P1 be the most serious and needs action straight away.","also":["P1","P2","P3","P4"]},{"id":"queue","g":"run","word":"Ticket queue","text":"The list o' requests and incidents waitin' to be picked up.","also":["ticket queues"]},{"id":"tiers","g":"run","word":"First line and second line","text":"Levels o' support: first line takes the call and fixes simple things; second line has deeper skills for harder ones. Also called tier 1 and tier 2.","also":["first-line support","tier 1","tier 2"]},{"id":"ic","g":"run","word":"Incident commander","text":"The one person who leads the response to an incident, so everyone knows who decides and who does what. The captain o' the emergency.","also":["incident commanders"]},{"id":"responsetime","g":"run","word":"Response time","text":"How long it takes before someone first picks up a request or incident.","also":["response times"]},{"id":"resolution","g":"run","word":"Resolution time","text":"How long it takes to fully sort out a request or incident, from report to fixed.","also":["resolution times","time to resolve"]},{"id":"mttr","g":"run","word":"Mean time to recover (MTTR)","text":"On average, how long it takes to get a service workin' again after it breaks. MTTR can mean slightly different things, so say what ye measure.","also":["MTTR","mean time to restore"]},{"id":"mtbf","g":"run","word":"Mean time between failures (MTBF)","text":"On average, how long a service runs before somethin' breaks.","also":["MTBF"]},{"id":"cmdb","g":"run","word":"Configuration management database (CMDB)","text":"The list o' all yer configuration items and how they connect, so ye can see what depends on what.","also":["CMDB"]},{"id":"asset","g":"run","word":"Asset","text":"Anythin' o' value ye own or pay for to run the service, like a laptop, a software licence or a domain.","also":["assets"],"noTip":1},{"id":"capplan","g":"run","word":"Capacity planning","text":"Makin' sure there will be enough computer power, storage and hands for what be comin'.","also":["capacity plan"]},{"id":"scaling","g":"run","word":"Scaling","text":"Copin' with more users by givin' a machine more power (scalin' up) or addin' more machines (scalin' out).","also":["scale up","scale out","scaling up","scaling out"]},{"id":"bcp","g":"run","word":"Business continuity","text":"Plans for keepin' the important things goin' when somethin' big goes wrong, like losin' an office, a key supplier or the computers.","also":["business continuity plan"]},{"id":"dr","g":"run","word":"Disaster recovery (DR)","text":"The plan and tools for gettin' a service back after somethin' serious, like losin' a whole data centre.","also":["disaster recovery"]},{"id":"rto","g":"run","word":"Recovery time objective (RTO)","text":"The longest a service may be down after a disaster before it must be workin' again.","also":["RTO"]},{"id":"rpo","g":"run","word":"Recovery point objective (RPO)","text":"How much recent data ye could afford to lose, measured in time. An RPO o' one hour means backups at least every hour.","also":["RPO"]},{"id":"redundancy","g":"run","word":"Redundancy","text":"Havin' spares ready, like a second server, so one failure doesn’t stop the service."},{"id":"failover","g":"run","word":"Failover","text":"Switchin' over to a spare system by itself when the usual one fails.","also":["fail over"]},{"id":"spof","g":"run","word":"Single point of failure","text":"One part that takes everythin' down with it when it breaks, because there be no spare.","also":["single points of failure","SPOF"]},{"id":"maintwin","g":"run","word":"Maintenance window","text":"A planned time when a service may be paused or slow for upkeep, announced to users in advance.","also":["maintenance windows","planned maintenance"]},{"id":"handover","g":"run","word":"Handover","text":"Passin' work, knowledge and responsibility to another person or crew, so nothin' gets dropped overboard.","also":["handovers"]},{"id":"kb","g":"run","word":"Knowledge base","text":"A collection o' help articles and answers, for users and for the crew.","also":["knowledge bases"]},{"id":"csat","g":"run","word":"Customer satisfaction (CSAT)","text":"A score from users sayin' how happy they were, often asked after a request be closed.","also":["CSAT"]},{"id":"supplier","g":"run","word":"Supplier","text":"An outside company ye rely on, like yer hostin' provider. Also called a vendor or third party.","also":["suppliers","vendor","vendors","third party"],"noTip":1},{"id":"retire","g":"run","word":"Service retirement","text":"Switchin' a service off for good, safely: tellin' its users, dealin' with its data and access, and stoppin' its costs.","also":["retiring a service"]},{"id":"eol","g":"run","word":"End of life (EOL)","text":"When a product stops gettin' updates or support from its maker, so it should be replaced.","also":["EOL","end-of-life"]},{"id":"cybersec","g":"sec","word":"Cybersecurity","text":"Protectin' systems and data from bein' broken into, stolen or damaged.","also":["cyber security"]},{"id":"authn","g":"sec","word":"Authentication","text":"Checkin' who someone be, usually with a password or a code. Often shortened to authn.","also":["authn"]},{"id":"authz","g":"sec","word":"Authorisation","text":"Checkin' what someone be allowed to do once ye know who they be. Often shortened to authz.","also":["authz","authorization"]},{"id":"mfa","g":"sec","word":"Multi-factor authentication (MFA)","text":"Loggin' in with two or more proofs, like a password plus a code on yer phone. Also called two-factor (2FA).","also":["MFA","2FA","two-factor","two-factor authentication"]},{"id":"sso","g":"sec","word":"Single sign-on (SSO)","text":"Loggin' in once to get into many systems, like usin' yer work account everywhere.","also":["SSO"]},{"id":"pwmgr","g":"sec","word":"Password manager","text":"An app that creates strong passwords and remembers 'em for ye.","also":["password managers"]},{"id":"secret","g":"sec","word":"Secret","text":"A password, key or other private code a program uses to get into somethin'. It must never be shared or written into the code.","also":["secrets"],"noTip":1},{"id":"apikey","g":"sec","word":"API key","text":"A secret code that lets a program use another service’s API, and shows who be usin' (and payin' for) it.","also":["API keys"]},{"id":"accesstoken","g":"sec","word":"Access token","text":"A temporary pass that proves a program be allowed in, so it doesn’t need yer password each time. Not the same as an AI token.","also":["access tokens"]},{"id":"encryption","g":"sec","word":"Encryption","text":"Scramblin' information so only someone with the right key can read it.","also":["encrypted","encrypt"]},{"id":"https","g":"sec","word":"HTTPS","text":"The secure way web pages travel, shown by the padlock in yer browser, so nobody in between can read or change 'em."},{"id":"cert","g":"sec","word":"SSL/TLS certificate","text":"A digital ID card that lets a website prove who it be and use HTTPS. It expires, so it must be renewed.","also":["TLS certificate","SSL certificate","certificate","certificates"]},{"id":"permissions","g":"sec","word":"Permissions","text":"The rules for who may see or change what.","also":["permission"],"noTip":1},{"id":"leastpriv","g":"sec","word":"Least privilege","text":"Givin' each person or program only the access they truly need, for only as long as they need it.","also":["principle of least privilege"]},{"id":"rbac","g":"sec","word":"Role-based access control (RBAC)","text":"Givin' access by role, like viewer or editor, rather than person by person.","also":["RBAC","role-based access"]},{"id":"vuln","g":"sec","word":"Vulnerability","text":"A weakness that someone could use to break in or cause harm.","also":["vulnerabilities"]},{"id":"zeroday","g":"sec","word":"Zero-day","text":"A weakness attackers know about before the makers have had any time to fix it.","also":["zero-days","zero day"]},{"id":"malware","g":"sec","word":"Malware","text":"Harmful software, like viruses, made to damage, spy or steal."},{"id":"ransomware","g":"sec","word":"Ransomware","text":"Malware that locks up yer files and demands doubloons to unlock 'em. Good backups be the best defence.","also":["ransomware attack"]},{"id":"phishing","g":"sec","word":"Phishing","text":"Fake messages that try to trick ye into givin' away passwords or doubloons, or openin' somethin' harmful.","also":["phishing email","phishing emails"]},{"id":"socialeng","g":"sec","word":"Social engineering","text":"Trickin' folk, rather than computers, into givin' access, like a fake call from “IT support”."},{"id":"firewall","g":"sec","word":"Firewall","text":"A guard that decides which network traffic may come in or go out.","also":["firewalls"]},{"id":"vpn","g":"sec","word":"VPN","text":"Short for virtual private network: a private, scrambled link over the internet, often used to reach work systems safely.","also":["virtual private network"]},{"id":"ddos","g":"sec","word":"Denial of service (DoS, DDoS)","text":"Floodin' a service with so much fake traffic that real folk can’t use it. DDoS means it comes from many computers at once.","also":["DoS","DDoS","denial of service","DDoS attack"]},{"id":"pentest","g":"sec","word":"Penetration test (pen test)","text":"Hirin' friendly experts to try to break in, so weaknesses be found before real attackers find 'em.","also":["pen test","pen testing","penetration testing","pentest"]},{"id":"audit","g":"sec","word":"Security audit","text":"A careful check o' how well somethin' be protected, against a list o' good practice.","also":["security audits"]},{"id":"threatmodel","g":"sec","word":"Threat modelling","text":"Thinkin' through who might attack somethin', how, and what ye would do to stop 'em.","also":["threat model","threat modeling"]},{"id":"breach","g":"sec","word":"Data breach","text":"When private information gets out to folk who shouldn’t have it, or be lost or changed without permission.","also":["data breaches"]},{"id":"pii","g":"sec","word":"Personal data","text":"Any information about a person who can be identified, like a name, email address or location. Also called PII.","also":["PII","personally identifiable information"]},{"id":"gdpr","g":"sec","word":"GDPR","text":"The European law on personal data (the UK has its own version): collect only what ye need, keep it safe, and let folk see or delete theirs.","also":["General Data Protection Regulation"]},{"id":"dataprot","g":"sec","word":"Data protection","text":"Lookin' after personal data properly and within the law.","also":["data protection law"]},{"id":"privacypolicy","g":"sec","word":"Privacy policy","text":"A public page sayin' what personal data ye collect, why, and what ye do with it.","also":["privacy statement","privacy notice"]},{"id":"consent","g":"sec","word":"Consent","text":"A person’s clear, free yes to their data bein' used in a particular way. They can take it back at any time.","also":["opt-in"],"noTip":1},{"id":"cookie","g":"sec","word":"Cookie","text":"A small file a website saves in yer browser to remember things, like bein' logged in. Some need yer consent first.","also":["cookies"],"noTip":1},{"id":"minimisation","g":"sec","word":"Data minimisation","text":"Collectin' and keepin' only the personal data ye really need for the job.","also":["data minimization"]},{"id":"retention","g":"sec","word":"Data retention","text":"How long data be kept before it be deleted. Keepin' it no longer than needed be safer and often the law.","also":["retention period"]},{"id":"anon","g":"sec","word":"Anonymisation","text":"Changin' data so nobody can reasonably be identified from it any more.","also":["anonymised","anonymization","anonymous data"]},{"id":"pseudo","g":"sec","word":"Pseudonymisation","text":"Swappin' names and other details for codes, with a key kept apart to link 'em back. It be still personal data.","also":["pseudonymised","pseudonymization"]},{"id":"dpa","g":"sec","word":"Data processing agreement (DPA)","text":"A contract sayin' how a supplier may handle personal data on yer behalf.","also":["DPA"]},{"id":"dpia","g":"sec","word":"Data protection impact assessment (DPIA)","text":"A careful look, before ye start, at how a plan to use personal data could affect folk and how to lower the risks.","also":["DPIA"]},{"id":"auditlog","g":"sec","word":"Audit log","text":"A record o' who did what and when, so actions can be checked later.","also":["audit logs","audit trail"]},{"id":"compliance","g":"sec","word":"Compliance","text":"Followin' the laws, rules and standards that apply to ye, and bein' able to show that ye do.","also":["compliant"]},{"id":"iso","g":"sec","word":"ISO 27001","text":"A well known international standard for managin' information security. Companies can be certified against it.","also":["ISO/IEC 27001"]},{"id":"soc","g":"sec","word":"SOC 2","text":"A US report, checked by outside auditors, showin' a company looks after customer data properly.","also":["SOC2"]},{"id":"agent","g":"ai","word":"Agent","text":"An AI that works on a task by itself: reads the code, makes changes, runs checks and reports back. Its work still gets checked.","also":["agents"]},{"id":"token","g":"ai","word":"Token","text":"The small pieces o' text an AI reads and writes, about three quarters o' a word each. AI use be counted in tokens, so fewer tokens leave more o' yer plan.","also":["tokens"]},{"id":"hook","g":"ai","word":"Hook","text":"A small command that runs by itself at a set moment, for example when an AI session starts, so the crew hears yer comments.","also":["hooks"]},{"id":"ai","g":"ai","word":"Artificial intelligence (AI)","text":"Computer systems that do things we usually think need a person, like writin', answerin' questions or recognisin' pictures.","also":["AI","artificial intelligence"],"noTip":1},{"id":"ml","g":"ai","word":"Machine learning (ML)","text":"A way o' makin' computers learn patterns from lots o' examples, instead o' givin' 'em exact rules.","also":["machine learning"]},{"id":"model","g":"ai","word":"Model","text":"The trained “brain” o' an AI system, built by learnin' from huge numbers o' examples. Models differ in skill, speed and price.","also":["models","AI model"],"noTip":1},{"id":"llm","g":"ai","word":"Large language model (LLM)","text":"An AI model trained on vast amounts o' text, so it can read and write language.","also":["LLM","LLMs"]},{"id":"genai","g":"ai","word":"Generative AI","text":"AI that creates new things, like text, pictures or code, rather than only sortin' or spottin' 'em.","also":["GenAI"]},{"id":"chatbot","g":"ai","word":"Chatbot","text":"A program ye talk with in everyday language, by typin' or speakin'.","also":["chatbots"]},{"id":"prompt","g":"ai","word":"Prompt","text":"What ye give an AI: yer question or instructions, plus anythin' ye hand it. Clearer prompts usually get better answers.","also":["prompts"]},{"id":"prompteng","g":"ai","word":"Prompt engineering","text":"The skill o' writin' prompts that get reliable, useful results."},{"id":"sysprompt","g":"ai","word":"System prompt","text":"Background instructions an AI gets before the conversation starts, settin' its role and rules. They weigh more than what ye type.","also":["system prompts","system instruction","system instructions"]},{"id":"context","g":"ai","word":"Context","text":"Everythin' the AI can see while it works: the instructions, yer messages, files it has read and earlier replies.","noTip":1},{"id":"ctxwin","g":"ai","word":"Context window","text":"How much an AI can keep in mind at once, measured in tokens. Past that, older parts get dropped or summarised.","also":["context windows"]},{"id":"session","g":"ai","word":"Session","text":"One workin' conversation with an AI, from start to finish. A new session starts with a fresh memory.","also":["sessions"],"noTip":1},{"id":"memory","g":"ai","word":"Memory","text":"Notes an AI keeps between sessions, so it remembers yer preferences and past decisions.","noTip":1},{"id":"hallucination","g":"ai","word":"Hallucination","text":"When an AI says somethin' that sounds sure o' itself but be made up or wrong. Check important facts.","also":["hallucinations","hallucinate","hallucinates"]},{"id":"training","g":"ai","word":"Training","text":"Teachin' a model by showin' it huge numbers o' examples, before anyone uses it.","also":["trained"],"noTip":1},{"id":"trainingdata","g":"ai","word":"Training data","text":"The examples a model learned from. Its knowledge stops at the date that data was collected.","also":["training set"]},{"id":"cutoff","g":"ai","word":"Knowledge cutoff","text":"The date an AI’s built-in knowledge ends. It won’t know about later things unless it looks 'em up.","also":["training cutoff"]},{"id":"finetune","g":"ai","word":"Fine-tuning","text":"Extra trainin' o' an existin' model on yer own examples, to make it better at one particular job.","also":["fine-tune","fine-tuned","fine tuning"]},{"id":"inference","g":"ai","word":"Inference","text":"An AI model actually bein' used to answer somethin', as opposed to bein' trained.","also":["model inference"]},{"id":"tooluse","g":"ai","word":"Tool use","text":"An AI bein' able to do things, not just talk: run commands, read files or search the web, through tools the app gives it.","also":["tool calling","tool call","tool calls"]},{"id":"subagent","g":"ai","word":"Subagent","text":"A helper AI that a main AI hands a smaller job to, and gets the result back from.","also":["subagents","sub-agent"]},{"id":"multiagent","g":"ai","word":"Multi-agent","text":"Several AIs workin' together on one piece o' work, each with its own part, like a small crew.","also":["multi-agent system"]},{"id":"autonomy","g":"ai","word":"Autonomy","text":"How much an AI may do on its own before it has to ask a person.","also":["autonomous"]},{"id":"hitl","g":"ai","word":"Human in the loop","text":"Keepin' a person involved to check or approve what the AI does at key points. In AI-gile that be ye.","also":["human-in-the-loop","HITL"]},{"id":"guardrails","g":"ai","word":"Guardrails","text":"Limits and checks that keep an AI’s actions safe, like needin' approval before anythin' goes live. They lower the risk o' mistakes, but don’t rule 'em out.","also":["guardrail"]},{"id":"rag","g":"ai","word":"Retrieval-augmented generation (RAG)","text":"Lettin' an AI look things up in yer own documents before it answers, so its answers rest on yer facts.","also":["RAG","retrieval augmented generation"]},{"id":"embedding","g":"ai","word":"Embedding","text":"Turnin' text into a list o' numbers that captures its meanin', so a computer can find things that mean similar things.","also":["embeddings"]},{"id":"vectordb","g":"ai","word":"Vector database","text":"A database built to search those lists o' numbers (embeddings), to find material with a similar meanin'.","also":["vector databases","vector store"]},{"id":"mcp","g":"ai","word":"Model Context Protocol (MCP)","text":"A common way to plug tools and data sources into AI apps, so an AI can use 'em.","also":["MCP"]},{"id":"temperature","g":"ai","word":"Temperature","text":"A setting for how adventurous an AI’s answers be. Low gives steadier, more predictable answers; high gives more varied ones. Neither makes it always right.","also":["model temperature"],"noTip":1},{"id":"multimodal","g":"ai","word":"Multimodal","text":"Able to work with more than one kind o' information, such as text, pictures and sound.","also":["multi-modal"]},{"id":"evals","g":"ai","word":"Evaluation (eval)","text":"A planned test o' how well an AI does on chosen examples, so ye can compare models or prompts.","also":["eval","evals"]},{"id":"bias","g":"ai","word":"Bias","text":"When an AI (or a person) leans unfairly one way, often because o' what it learned from.","also":["biased"],"noTip":1},{"id":"responsible","g":"ai","word":"Responsible AI","text":"Usin' AI fairly, safely and honestly, with folk still answerable for the results.","also":["ethical AI"]},{"id":"injection","g":"ai","word":"Prompt injection","text":"A trick where hidden instructions in a web page or file try to make an AI do somethin' its user didn’t ask for.","also":["prompt injections"]},{"id":"ratelimit","g":"ai","word":"Rate limit","text":"A cap on how many requests ye may send to a service in a set time. Go over it and ye have to wait.","also":["rate limits","rate limited"]},{"id":"usagelimit","g":"ai","word":"Usage limit","text":"How much AI work yer plan allows in a period, after which it pauses or costs more.","also":["usage limits"]},{"id":"vibe","g":"ai","word":"Vibe coding","text":"Buildin' software mostly by describin' what ye want to an AI and lettin' it write the code.","also":["vibe-coding"]},{"id":"budget","g":"money","word":"Budget","text":"The amount o' doubloons set aside for somethin'.","also":["budgets"],"noTip":1},{"id":"costest","g":"money","word":"Cost estimate","text":"A best guess at what somethin' will cost before ye start.","also":["cost estimates"]},{"id":"roi","g":"money","word":"Return on investment (ROI)","text":"What ye get back compared with what ye put in. If it be positive, it was worth it.","also":["ROI"]},{"id":"tco","g":"money","word":"Total cost of ownership (TCO)","text":"Everythin' somethin' really costs over its whole life, not just the price to buy it: runnin', support, upgrades and finally retirin' it.","also":["TCO"]},{"id":"capex","g":"money","word":"CapEx and OpEx","text":"CapEx be doubloons spent up front on things ye keep; OpEx be ongoin' spendin', like monthly bills.","also":["CapEx","OpEx","capital expenditure","operating expenditure"]},{"id":"subscription","g":"money","word":"Subscription","text":"Payin' regularly, usually monthly or yearly, to keep usin' somethin'.","also":["subscriptions"],"noTip":1},{"id":"saas","g":"money","word":"Software as a service (SaaS)","text":"Software ye use online and pay for by subscription, while the maker runs it for ye.","also":["SaaS"]},{"id":"payg","g":"money","word":"Pay as ye go","text":"Payin' only for what ye use, like cloud computin' or AI tokens.","also":["pay-as-you-go","usage-based pricing"]},{"id":"overage","g":"money","word":"Overage","text":"Use above what yer plan includes, which can cost extra doubloons.","also":["overages","overage charges"]},{"id":"billingalert","g":"money","word":"Billing alert","text":"A message when spendin' or use reaches a level ye chose. It warns ye, but doesn’t always stop further charges.","also":["billing alerts","spending alert"]},{"id":"freetier","g":"money","word":"Free tier","text":"A free level o' a paid service, with limits. Handy for startin' out.","also":["free plan"]},{"id":"pricing","g":"money","word":"Pricing plan","text":"The different packages a service sells, each with its own price and limits.","also":["pricing plans","price plan"]},{"id":"licence","g":"money","word":"Licence","text":"The rules for how ye may use, copy, change or share somethin' someone else made, such as software, fonts or pictures.","also":["licences","license","licenses"],"noTip":1},{"id":"opensource","g":"money","word":"Open source","text":"Software whose code anyone can read, use and often change for free, under the rules o' its licence.","also":["open-source","open source software","OSS"]},{"id":"osslicence","g":"money","word":"Open source licence","text":"The rules that come with open source code. Some let ye do almost anythin' (like MIT); some ask ye to share yer changes too (like GPL).","also":["open source licences","MIT licence","GPL"]},{"id":"proprietary","g":"money","word":"Proprietary","text":"Owned by a company and not free to copy or change. The opposite o' open source.","also":["proprietary software"]},{"id":"copyright","g":"money","word":"Copyright","text":"The legal right o' a creator to control copies o' their work, includin' code and writin'.","also":["copyrighted"],"noTip":1},{"id":"ip","g":"money","word":"Intellectual property (IP)","text":"Ideas and creations the law treats as owned, like code, designs, names and logos.","also":["intellectual property"]},{"id":"tos","g":"money","word":"Terms of service","text":"The rules ye agree to when ye use a service.","also":["terms and conditions","terms of use"]},{"id":"contract","g":"money","word":"Contract","text":"A written agreement between two sides that the law will back up.","also":["contracts"],"noTip":1},{"id":"sow","g":"money","word":"Statement of work (SOW)","text":"A document settin' out exactly what work will be done, by when and for how many doubloons.","also":["SOW"]},{"id":"fixedprice","g":"money","word":"Fixed price","text":"An agreed price for the whole job, however long it takes.","also":["fixed-price"]},{"id":"tm","g":"money","word":"Time and materials","text":"Payin' for the hours really worked and the things really used, rather than a set price.","also":["T&M"]},{"id":"invoice","g":"money","word":"Invoice","text":"A bill askin' for payment for work done or goods supplied.","also":["invoices"],"noTip":1},{"id":"lockin","g":"money","word":"Vendor lock-in","text":"When movin' away from a supplier be so hard or costly that ye be stuck with 'em.","also":["lock-in"]},{"id":"procurement","g":"money","word":"Procurement","text":"The process o' choosin' and buyin' from suppliers."},{"id":"servicecredit","g":"money","word":"Service credit","text":"Doubloons back or a discount ye get when a supplier misses its SLA.","also":["service credits"]}]}};
